"""Validate checked-in HTML and pages generated by the static site builder."""

from __future__ import annotations

from pathlib import Path
import subprocess
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[1]


def html_sources() -> list[Path]:
    """Return tracked and non-ignored HTML source files, excluding build output."""
    result = subprocess.run(
        ["git", "ls-files", "-z", "-c", "-o", "--exclude-standard"],
        cwd=ROOT,
        check=True,
        capture_output=True,
    )
    return sorted(
        ROOT / name.decode("utf-8")
        for name in result.stdout.split(b"\0")
        if name and Path(name.decode("utf-8")).suffix.lower() == ".html"
    )


def project_python() -> Path:
    """Use the project environment for optional website dependencies."""
    candidates = (
        ROOT / ".venv" / "bin" / "python",
        ROOT / ".venv" / "Scripts" / "python.exe",
    )
    return next((path for path in candidates if path.is_file()), Path(sys.executable))


def main() -> int:
    with tempfile.TemporaryDirectory(prefix="pathplanning-html-lint-") as temporary:
        generated_site = Path(temporary) / "site"
        build = subprocess.run(
            [
                str(project_python()),
                str(ROOT / "website" / "build_site.py"),
                "--output",
                str(generated_site),
            ],
            cwd=ROOT,
            check=False,
        )
        if build.returncode:
            return build.returncode

        return subprocess.run(
            [
                "npm",
                "run",
                "lint:html",
                "--",
                *(str(path) for path in html_sources()),
                str(generated_site),
            ],
            cwd=ROOT,
            check=False,
        ).returncode


if __name__ == "__main__":
    raise SystemExit(main())
